function resolveRowPassword(row: Record<string, unknown>, column: string): string {
  const key = row[column] as string | undefined;
  return key ? resolvePassword(key) : '';
}

// ---------- Given ----------

// 'User is logged in as {string}' moved to steps/support/common.steps.ts (was defined
// identically in dash/invoice/waiver.steps.ts — a Cucumber AmbiguousDefinitionError hazard).

Given('User is logged in as {string} on a fresh empty test tenant', async function (this: ScenarioContext, role: string) {
  // Reuses a cached per-role session instead of an interactive UI login — see
  // steps/support/common.steps.ts's "User is logged in as {string}" and auth-setup.ts's
  // getOrCreateRoleAuthState() for why.
  const email = this.testData.Email as string;
  const password = resolveRowPassword(this.testData, 'PasswordKey');

  // Super Admin is currently blocked by the live backend's login rate limiter — skip
  // rather than fail. Do not remove without explicit confirmation it's unlocked again.
  if (email?.toLowerCase().includes('superadmin') || role?.toLowerCase().includes('super admin')) {
    return 'skipped';
  }

  const browser = getSharedBrowser();
  await this.context?.close();
  const authed = await getAuthenticatedPage(browser, email, password);
  this.context = authed.context;
  this.page = authed.page;
  this.testData.Role = role;
});

